class Zipper {
    Zipper up;
    Zipper left;
    Zipper right;
    int value;

    Zipper(int val) {
        this.value = val;
    }

    BinaryTree toTree() {
        Zipper top = this;
        while (top.up != null) {
            top = top.up;
        }
        return new BinaryTree(top);
    }

    int getValue() {
        return value;
    }

    Zipper setLeft(Zipper leftChild) {
        this.left = leftChild;
        if (leftChild != null) {
            leftChild.up = this;
        }
        return this;
    }

    Zipper setRight(Zipper rightChild) {
        this.right = rightChild;
        if (rightChild != null) {
            rightChild.up = this;
        }
        return this;
    }

    void setValue(int val) {
        this.value = val;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Zipper)) return false;
        Zipper other = (Zipper) o;
        return value == other.value
            && equals(left, other.left)
            && equals(right, other.right);
    }

    static boolean equals(Zipper a, Zipper b) {
        if (a == null) return b == null;
        if (b == null) return false;
        return a.value == b.value && equals(a.left, b.left) && equals(a.right, b.right);
    }

    @Override
    public int hashCode() {
        return value;
    }
}

class BinaryTree {
    private final Zipper root;

    BinaryTree(int value) {
        this.root = new Zipper(value);
    }

    BinaryTree(Zipper root) {
        this.root = root;
    }

    Zipper getRoot() {
        return root;
    }

    String printTree() {
        return print(root);
    }

    private static String print(Zipper z) {
        return "value: " + z.value
            + ", left: " + printChild(z.left)
            + ", right: " + printChild(z.right);
    }

    private static String printChild(Zipper z) {
        return z == null ? "null" : "{ " + print(z) + " }";
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof BinaryTree)) return false;
        return Zipper.equals(root, ((BinaryTree) o).root);
    }

    @Override
    public int hashCode() {
        return 0;
    }
}
